  /// < 字节数 (不含结尾 \0)
  @ffi.Uint64()
  external int size;
}

/// 只读字符串视图: 指向调用方内存 (UTF-8), 不要求 NUL 结尾
final class AgentxxStringView extends ffi.Struct {
  /// < 指向 UTF-8 字节序列
  external ffi.Pointer<ffi.Char> data;

  /// < 字节数
  @ffi.Uint64()
